var chain = new NodeChain<int>()
    .Add(node.First(), node.At(5))
    .Add(node.At(10), node.At(20))
    .Add(node.At(30), node.End());

foreach (var x in chain)
    Console.WriteLine(x);

var range = new NodeRange<int>(node.First(), node.At(10));

foreach (var x in range)
    Console.WriteLine(x);

var slice = new NodeSlice<int>(node.At(5), 10);

foreach (var x in slice)
    Console.WriteLine(x);
